// Generate a document, then open its bytes and edit them in one transaction, and save
// incrementally: the generated bytes unchanged, then the appended revision. The TS twin of
// crates/laminapdf/examples/generate_then_edit.rs.
import { Builder, Document, Font } from "@laminapdf/sdk";

/** The document's bytes: the generated file followed by the edit's revision. Needs `init({ text: true })`. */
export function generateThenEdit(): Uint8Array<ArrayBuffer> {
  // 1. Generate and save (a new document is always a full rewrite).
  const b = new Builder({
    id: new TextEncoder().encode("lamina-ex-edit!!"),
    producer: "lamina examples",
    creationDate: "D:20261030120000Z",
  });
  const page = b.page("A4");
  page.surface().text("Draft report", { font: Font.standard("Helvetica"), size: 20, at: [72, 96] });
  page.finish();
  b.metadata({ title: "Draft report" });
  const generated = b.finish().save();

  // 2. Open the bytes and edit them: one transaction, which `undo` could revert.
  const doc = Document.open(generated);
  doc.transact((tx) => tx.setInfo({ title: "Final report", author: "Ada Lovelace" }, "D:20261030130000Z"));

  // 3. Save incrementally: the generated bytes, unchanged, then the appended revision.
  const edited = doc.save({ mode: "incremental" });
  if (!generated.every((byte, i) => edited[i] === byte) || doc.info.title !== "Final report") {
    throw new Error("the incremental save did not append to the generated file");
  }
  doc.free();
  return edited;
}
